import { contextBridge, ipcRenderer } from "electron";

/**
 * Sandboxed preload for the update HUD window.
 * Channel names stay inlined so this file does not pull ipcEvents at runtime.
 */
const DATA = "update-prompt:data";
const ACTION = "update-prompt:action";
const RESIZE = "update-prompt:resize";

let last: unknown = null;
let handler: ((data: unknown) => void) | null = null;

ipcRenderer.on(DATA, (_event, data) => {
  last = data;
  handler?.(data);
});

contextBridge.exposeInMainWorld("updatePrompt", {
  onData: (cb: (data: unknown) => void) => {
    handler = cb;
    if (last) cb(last);
  },
  action: (type: string) => {
    ipcRenderer.send(ACTION, { type });
  },
  resize: (width: number, height: number) => {
    ipcRenderer.send(RESIZE, { width, height });
  },
});
